     1	import { sql } from "bun";
     2	
     3	// Postgres (Cloud SQL). Schema in migrations/.
     4	export type Report = { id: string; company: string; status: string; created_at: string };
     5	
     6	export async function getReport(id: string): Promise<Report | undefined> {
     7	  const rows = await sql`select * from reports where id = ${id}`;
     8	  return rows[0];
     9	}
    10	
    11	export async function listSections(reportId: string) {
    12	  return sql`select id, name, body from sections where report_id = ${reportId} order by position`;
    13	}
    14	
    15	export async function saveSection(reportId: string, name: string, body: string) {
