    20	}
=== src/queue.ts
     1	// Cloud Tasks queue "sections" (created in deploy.sh). One task per section.
     2	const QUEUE = process.env.SECTIONS_QUEUE!;
     3	
     4	export async function enqueueSection(reportId: string, section: string): Promise<void> {
     5	  await fetch(`https://cloudtasks.googleapis.com/v2/${QUEUE}/tasks`, {
     6	    method: "POST",
     7	    body: JSON.stringify({
     8	      task: {
     9	        httpRequest: {
    10	          url: `${process.env.WORKER_URL}/tasks/generate-section`,
    11	          body: btoa(JSON.stringify({ reportId, section })),
    12	        },
    13	      },
    14	    }),
    15	  });
    16	}
=== src/worker.ts
     1	import { generateSection } from "./llm";
     2	import { getReport, saveSection } from "./db";
     3	
     4	// Cloud Tasks HTTP target: POST /tasks/generate-section with { reportId, section }.
     5	export async function handleGenerateSection(req: Request): Promise<Response> {
     6	  const { reportId, section } = (await req.json()) as { reportId: string; section: string };
     7	  const report = await getReport(reportId);
     8	  if (!report) return new Response("gone", { status: 200 });
     9	  const body = await generateSection(report.company, section);
    10	  await saveSection(reportId, section, body);
    11	  return new Response("ok");
    12	}
